// Generates prisma/dev.sqlite.prisma from prisma/schema.prisma for offline local development.
// Same models, SQLite provider, no directUrl. Do not edit the generated file.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const src = readFileSync(join(root, "prisma/schema.prisma"), "utf8");

const out = src
  .replace(/provider\s*=\s*"postgresql"/, 'provider = "sqlite"')
  .replace(/^\s*directUrl\s*=.*$/m, "");

if (out === src || !out.includes('provider = "sqlite"')) {
  console.error("dev-schema: could not switch provider to sqlite");
  process.exit(1);
}

writeFileSync(
  join(root, "prisma/dev.sqlite.prisma"),
  `// GENERATED by scripts/dev-schema.mjs from schema.prisma — do not edit.\n${out}`,
);
